def match(orders):
    buys = []  # min heap: (price, arrival_time, id, qty) - sorted by -price, then arrival_time
    sells = []  # min heap: (price, arrival_time, id, qty) - sorted by price, then arrival_time

    order_map = {}  # maps id to (side, index_in_queue)
    trades = []
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, queue = order_map[order_id]
                # Mark as cancelled by setting qty to 0
                for i, (p, t, oid, qty) in enumerate(queue):
                    if oid == order_id:
                        queue[i] = (p, t, oid, 0)
                        del order_map[order_id]
                        break

        elif order[0] == 'market':
            order_id = order[1]
            side = order[2]
            qty = order[3]

            if side == 'buy':
                # Match against sells (lowest price first, then earliest)
                while qty > 0 and sells:
                    # Remove cancelled orders from front
                    while sells and sells[0][3] == 0:
                        _, _, _, _ = sells.pop(0)

                    if not sells:
                        break

                    price, t, sell_id, sell_qty = sells.pop(0)

                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, price, trade_qty])

                    qty -= trade_qty
                    sell_qty -= trade_qty

                    if sell_qty > 0:
                        sells.insert(0, (price, t, sell_id, sell_qty))
                    else:
                        del order_map[sell_id]
